        elif choice == '5':
            # Return to main menu
            return

        else:
            print("\nInvalid choice! Please try again.")

        input("\nPress Enter to continue...")

def reader_session():
    """Handle the reader's session."""
    print("\n=== Reader Login ===")
    reader_name = input("Enter your name: ")
    print(f"\nWelcome, {reader_name}!")

    while True:
        display_reader_menu()
        choice = input("Enter your choice (1-8): ")

        if choice == '1':
            # View all available books
            display_all_books()

        elif choice == '2':
            # Search books by author
            search_books_by_author()

        elif choice == '3':
            # Search books by genre
            search_books_by_genre()

        elif choice == '4':
            # View all authors
            print("\n=== All Authors ===")
            if not authors:
                print("No authors in the library!")
            else:
                for author in authors:
                    print(f"- {author.name} ({len(author.books)} books)")

        elif choice == '5':
            # Borrow a book
            print("\n=== Borrow a Book ===")
            display_all_books()
            isbn = input("\nEnter the ISBN of the book you want to borrow: ")

            # Find the book and check if it's available
            for author in authors:
                for book in author.books:
                    if book.get('isbn') == isbn:
                        if book.get('is_available', True):
                            book['is_available'] = False
                            book['borrower'] = reader_name
                            print(f"\nSuccessfully borrowed '{book['title']}'")
                            storage.save_library_data(authors)  # Save the updated state
                            break
                        else:
                            print("\nSorry, this book is already borrowed.")
                            break
                else:
                    continue
                break
            else:
                print("\nBook not found. Please check the ISBN and try again.")

        elif choice == '6':
            # Return a book
            print("\n=== Return a Book ===")
            borrowed_books = []
            for author in authors:
                for book in author.books:
                    if book.get('borrower') == reader_name:
                        borrowed_books.append((book['title'], book.get('isbn')))

            if not borrowed_books:
                print("You haven't borrowed any books.")
                continue

            print("\nYour borrowed books:")
            for i, (title, isbn) in enumerate(borrowed_books, 1):
                print(f"{i}. {title} (ISBN: {isbn})")

            isbn = input("\nEnter the ISBN of the book you want to return: ")

            # Find the book and return it
            for author in authors:
                for book in author.books:
                    if book.get('isbn') == isbn and book.get('borrower') == reader_name:
                        book['is_available'] = True
                        book['borrower'] = None
                        print(f"\nSuccessfully returned '{book['title']}'")
                        storage.save_library_data(authors)  # Save the updated state
                        break
                else:
                    continue
                break
            else:
                print("\nBook not found in your borrowed books. Please check the ISBN and try again.")

        elif choice == '7':
            # View borrowed books
            print("\n=== Your Borrowed Books ===")
            found = False
            for author in authors:
                for book in author.books:
                    if book.get('borrower') == reader_name:
                        if not found:
                            found = True
                        print(f"\nTitle: {book['title']}")
                        print(f"Author: {author.name}")
                        print(f"ISBN: {book.get('isbn', 'N/A')}")
