        elif choice == '8':
            # Return to main menu
            return

        else:
            print("\nInvalid choice! Please try again.")

        input("\nPress Enter to continue...")

def main():
    # Load existing library data
    global authors
    authors = storage.load_library_data()

    while True:
        display_main_menu()
        choice = input("Enter your choice (1-3): ")

        if choice == '1':
            # Reader mode
            reader_session()

        elif choice == '2':
            # Author mode
            print("\n=== Author Login ===")
            author_name = input("Enter your name: ")

            # Find existing author or create new one
            current_author = next((a for a in authors if a.name.lower() == author_name.lower()), None)
            if current_author is None:
                current_author = Author(author_name)
                authors.append(current_author)
