                print(f"'{book_title}' is already in {self.name}'s collection")
                return

        # Create new book entry with title and additional info
        book_entry = {'title': book_title, **book_info}
        self.books.append(book_entry)
        print(f"Added '{book_title}' to {self.name}'s book collection")

    def remove_book(self, book_title):
        """Remove a book from the author's collection."""
        for book in self.books:
            if book['title'] == book_title:
                self.books.remove(book)
                print(f"Removed '{book_title}' from {self.name}'s collection")
                return
        print(f"'{book_title}' not found in {self.name}'s collection")

    def update_book(self, book_title, **new_info):
        """Update information for an existing book."""
        for book in self.books:
            if book['title'] == book_title:
                book.update(new_info)
                print(f"Updated information for '{book_title}'")
                return
        print(f"'{book_title}' not found in {self.name}'s collection")

    def get_books(self):
        """Return the list of all books by this author."""
        return self.books

    def display_books(self):
        """Display all books by this author."""
        print(f"\nBooks by {self.name}:")
        if not self.books:
            print("No books in collection yet.")
        else:
            for i, book in enumerate(self.books, 1):
                print(f"{i}. {book['title']}")
                # Print additional book information if available
                for key, value in book.items():
                    if key != 'title':
                        print(f"   {key}: {value}")


